@operation("GeoRemoteHistogramMatch")
def relative_histogram_match(args, output_dir=None):
    import numpy as np
    from skimage.exposure import match_histograms
    loaded, reference = _pair(args, complete=False)
    image, valid, _, _ = loaded
    result = np.zeros(image.shape)
    result[valid] = match_histograms(image[valid], reference[valid], channel_axis=None)
    return _image_result(args, output_dir, loaded, result, args["input_unit"])
